t.script:
//
document.addEventListener('DOMContentLoaded', function() {
    console.log('🚀 === INICIANDO SISTEMA DE PERMISOS ===');

    // Configurar SweetAlert2 con estilos personalizados
    const swalConfig = {
        customClass: {
            container: 'custom-alert',
            popup: 'custom-alert',
            title: 'custom-alert',
            content: 'custom-alert',
            confirmButton: 'custom-alert',
            cancelButton: 'custom-alert'
        },
        buttonsStyling: false,
        showClass: {
            popup: 'animate__animated animate__fadeInDown animate__faster'
        },
        hideClass: {
            popup: 'animate__animated animate__fadeOutUp animate__faster'
        }
    };

    // Elements
    const periodCards = document.querySelectorAll('.period-card');
    const hoursContainer = document.getElementById('hoursContainer');
    const dateToContainer = document.getElementById('dateToContainer');
    const attachmentContainer = document.getElementById('attachmentContainer');
    const holidayStatusSelect = document.getElementById('holiday_status_id');
    const fileInput = document.getElementById('file_input');
    const fileList = document.getElementById('file_list');
    const form = document.getElementById('leaveRequestForm');

    // Función para convertir errores técnicos a mensajes amigables
    function getFriendlyErrorMessage(errorData) {
        console.log('🔄 Procesando error:', errorData);

        const errorCode = errorData.error_code || 'UNKNOWN';
        const message = errorData.error || errorData.message || 'Error desconocido';
        const suggestion = errorData.suggestion || 'Contacta al administrador del sistema.';

        const errorMappings = {
            'EMPLOYEE_NOT_FOUND': {
                title: '👤 Perfil Incompleto',
                icon: '👤',
                message: 'Tu perfil de empleado no está configurado correctamente.',
                suggestion: 'Contacta al administrador del sistema para configurar tu perfil de empleado.'
            },
            'VALIDATION_ERROR': {
                title: '📋 Datos Incompletos',
                icon: '📋',
                message: message,
                suggestion: 'Verifica que todos los campos requeridos estén completados correctamente.'
            },
            'INVALID_LEAVE_TYPE': {
                title: '📝 Tipo de Permiso Inválido',
                icon: '📝',
                message: 'El tipo de permiso seleccionado no es válido.',
                suggestion: 'Selecciona un tipo de permiso válido de la lista disponible.'
            },
            'DATE_OVERLAP': {
                title: '📅 Conflicto de Fechas',
                icon: '⚠️',
                message: message,
                suggestion: 'Selecciona fechas diferentes o cancela las solicitudes existentes.',
                showDetails: true,
                details: errorData.details
            },
            'INSUFFICIENT_BALANCE': {
                title: '💰 Saldo Insuficiente',
                icon: '💰',
                message: message,
                suggestion: 'Contacta a Recursos Humanos para verificar tu saldo de permisos o solicitar una asignación adicional.'
            },
            'INTERNAL_ERROR': {
                title: '🔧 Error del Sistema',
                icon: '🔧',
                message: 'Ocurrió un error interno en el sistema.',
                suggestion: 'Por favor intenta nuevamente. Si el problema persiste, contacta al administrador del sistema.'
            }
        };

        return errorMappings[errorCode] || {
            title: '❌ Error Inesperado',
            icon: '❌',
            message: message,
            suggestion: suggestion
        };
    }

    // Función mejorada para mostrar errores con SweetAlert2
    function showErrorModal(errorData, technicalError) {
        console.log('🎨 Mostrando modal de error mejorado');

        const friendlyError = getFriendlyErrorMessage(errorData);

        let htmlContent = `
            <div class="text-left">
                <div class="flex items-center mb-6">
                    <div class="flex-shrink-0 w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mr-4">
                        <span class="text-3xl">${friendlyError.icon}</span>
                    </div>
                    <div>
                        <h3 class="text-xl font-bold text-gray-900">${friendlyError.title}</h3>
                        <p class="text-sm text-gray-500">Solicitud de permiso</p>
                    </div>
                </div>

                <div class="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
                    <p class="text-red-800 font-medium">${friendlyError.message}</p>
                </div>

                <div class="bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <div class="flex items-start">
                        <div class="flex-shrink-0 w-6 h-6 bg-blue-500 rounded-full flex items-center justify-center mr-3 mt-0.5">
                            <span class="text-white text-sm">💡</span>
                        </div>
                        <div>
                            <h4 class="font-semibold text-blue-900 mb-1">¿Qué puedes hacer?</h4>
                            <p class="text-blue-800 text-sm">${friendlyError.suggestion}</p>
                        </div>
                    </div>
                </div>
        `;

        // Agregar detalles específicos para conflictos de fechas
        if (friendlyError.showDetails && friendlyError.details) {
            htmlContent += `
                <div class="mt-4 bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                    <h4 class="font-semibold text-yellow-900 mb-3">📋 Solicitudes en conflicto:</h4>
                    <div class="space-y-2">
            `;

            friendlyError.details.forEach(function(leave, index) {
                const stateText = {
                    'confirm': 'Pendiente de Aprobación',
                    'validate1': 'Primera Aprobación',
                    'validate': 'Aprobado'
                }[leave.state] || leave.state;

                htmlContent += `
                    <div class="bg-white border border-yellow-300 rounded p-3">
                        <div class="flex justify-between items-start">
                            <div>
                                <p class="font-medium text-gray-800">${leave.type}</p>
                                <p class="text-sm text-gray-600">Del ${leave.date_from} al ${leave.date_to}</p>
                            </div>
                            <span class="px-2 py-1 bg-yellow-100 text-yellow-800 text-xs rounded-full">${stateText}</span>
                        </div>
                    </div>
                `;
            });

            htmlContent += `
                    </div>
                </div>
            `;
        }

        // Agregar información técnica si está disponible
        if (technicalError) {
            htmlContent += `
                <details class="mt-4">
                    <summary class="cursor-pointer text-gray-600 font-medium">🔧 Información técnica</summary>
                    <div class="mt-2 p-3 bg-gray-800 rounded text-gray-300 text-xs font-mono break-all">
                        ${technicalError}
                    </div>
                </details>
            `;
        }

        htmlContent += '</div>';

        Swal.fire({
            ...swalConfig,
            icon: 'error',
            title: false, // No mostrar título por defecto
            html: htmlContent,
            confirmButtonText: 'Entendido',
            allowOutsideClick: false,
            allowEscapeKey: true,
            customClass: {
                ...swalConfig.customClass,
                htmlContainer: 'text-left'
            }
        });
    }

    // Period selection
    periodCards.forEach(function(card) {
        card.addEventListener('click', function() {
            console.log('🖱️ Período seleccionado:', this.dataset.period);

            periodCards.forEach(function(c) {
                c.classList.remove('active');
            });
            this.classList.add('active');

            // Add touch feedback
            this.style.transform = 'scale(0.95)';
            const self = this;
            setTimeout(function() {
                self.style.transform = '';
            }, 150);

            handlePeriodChange(this.dataset.period);
        });
    });

    function handlePeriodChange(period) {
        console.log('⚙️ Manejando cambio de período:', period);

        // Reset all hidden inputs
        document.getElementById('request_unit_half').value = '';
        document.getElementById('request_unit_hours').value = '';
        document.getElementById('request_date_from_period').value = '';

        switch(period) {
            case 'full_day':
                dateToContainer.classList.remove('hidden');
                hoursContainer.classList.add('hidden');
                break;

            case 'morning':
                document.getElementById('request_unit_half').value = 'true';
                document.getElementById('request_date_from_period').value = 'am';
                dateToContainer.classList.add('hidden');
                hoursContainer.classList.add('hidden');
                updateDateTo();
                break;

            case 'afternoon':
                document.getElementById('request_unit_half').value = 'true';
                document.getElementById('request_date_from_period').value = 'pm';
                dateToContainer.classList.add('hidden');
                hoursContainer.classList.add('hidden');
                updateDateTo();
                break;

            case 'custom_hours':
                document.getElementById('request_unit_hours').value = 'true';
                dateToContainer.classList.add('hidden');
                hoursContainer.classList.remove('hidden');
                updateDateTo();
                break;
        }
    }

    function updateDateTo() {
        const dateFrom = document.getElementById('request_date_from').value;
        if (dateFrom) {
            document.getElementById('request_date_to').value = dateFrom;
        }
    }

    // Handle leave type change
    holidayStatusSelect.addEventListener('change', function() {
        console.log('📝 Cambio de tipo de permiso:', this.value);

        const selectedOption = this.options[this.selectedIndex];
        const supportDocument = selectedOption.dataset.supportDocument === 'true';

        if (supportDocument) {
            attachmentContainer.classList.remove('hidden');
            attachmentContainer.classList.add('slide-up');
        } else {
            attachmentContainer.classList.add('hidden');
        }
    });

    // File handling
    fileInput.addEventListener('change', function() {
        console.log('📁 Archivos seleccionados:', this.files.length);
        fileList.innerHTML = '';

        for (let i = 0; i < this.files.length; i++) {
            const file = this.files[i];
            const fileSizeNum = (file.size / 1024 / 1024).toFixed(2);

            const fileItem = document.createElement('div');
            fileItem.className = 'flex items-center justify-between p-3 bg-blue-50 border border-blue-200 rounded-lg slide-up';

            fileItem.innerHTML = `
                <div class="flex items-center space-x-3">
                    <i class="fas fa-file text-blue-500"></i>
                    <div>
                        <p class="font-medium text-gray-800 truncate max-w-[200px]">${file.name}</p>
                        <p class="text-sm text-gray-500">${fileSizeNum} MB</p>
                    </div>
                </div>
                <i class="fas fa-check text-green-500"></i>
            `;

            fileList.appendChild(fileItem);
        }
    });

    // Enhanced Toast notification
    function showToast(message, type) {
        console.log('📢 Toast:', message, type);

        const toast = Swal.mixin({
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 4000,
            timerProgressBar: true,
            didOpen: (toast) => {
                toast.addEventListener('mouseenter', Swal.stopTimer)
                toast.addEventListener('mouseleave', Swal.resumeTimer)
            }
        });

        let icon = 'info';
        if (type === 'success') icon = 'success';
        else if (type === 'error') icon = 'error';
        else if (type === 'warning') icon = 'warning';

        toast.fire({
            icon: icon,
            title: message
        });
    }

    // Form submission with comprehensive validation
    form.addEventListener('submit', function(e) {
        e.preventDefault();
        e.stopPropagation();

        console.log('📋 Procesando envío de formulario');

        // Verificar que no haya otro envío en progreso
        const submitBtn = form.querySelector('button[type="submit"]');
        if (submitBtn.disabled) {
            console.log('⚠️ Envío ya en progreso, ignorando');
            return false;
        }

        // Get form data
        const dateFrom = document.getElementById('request_date_from').value;
        const dateTo = document.getElementById('request_date_to').value || dateFrom;
        const leaveType = document.getElementById('holiday_status_id').value;
        const description = document.getElementById('private_name').value.trim();

        // Basic validation
        if (!leaveType) {
            showToast('Por favor selecciona un tipo de permiso', 'error');
            document.getElementById('holiday_status_id').focus();
            return;
        }

        if (!dateFrom) {
            showToast('Por favor selecciona la fecha de inicio', 'error');
            document.getElementById('request_date_from').focus();
            return;
        }

        if (!description) {
            showToast('Por favor agrega una descripción', 'error');
            document.getElementById('private_name').focus();
            return;
        }

        console.log('✅ Validación básica completada');

        // Show loading state
        const loadingSpinner = submitBtn.querySelector('.loading-spinner');
        const submitText = submitBtn.querySelector('.submit-text');

        loadingSpinner.classList.remove('hidden');
        submitText.innerHTML = '<i class="fas fa-spinner loading-spinner mr-2"></i>Enviando...';
        submitBtn.disabled = true;

        // Submit form
        const formData = new FormData(form);

        fetch('/leave/request/submit', {
            method: 'POST',
            body: formData
        })
        .then(function(response) {
            console.log('Respuesta HTTP:', response.status);

            const contentType = response.headers.get('content-type');
            if (contentType && contentType.includes('application/json')) {
                return response.json();
            } else {
                return response.text().then(function(text) {
                    console.log('Respuesta no-JSON:', text);
                    throw new Error('Respuesta del servidor no es JSON válido');
                });
            }
        })
        .then(function(data) {
            console.log('Datos de respuesta:', data);

            if (data.success) {
                console.log('🎉 ÉXITO: Solicitud enviada');

                Swal.fire({
                    ...swalConfig,
                    icon: 'success',
                    title: '¡Solicitud Enviada!',
                    html: `
                        <div class="text-center">
                            <div class="text-6xl mb-4">🎉</div>
                            <p class="text-lg mb-4">Tu solicitud de permiso ha sido enviada exitosamente.</p>
                            <div class="bg-green-50 border border-green-200 rounded-lg p-4">
                                <p class="text-green-800 font-medium">¿Qué sigue?</p>
                                <ul class="text-green-700 text-sm mt-2 list-disc list-inside text-left">
                                    <li>Recibirás una notificación cuando sea revisada</li>
                                    <li>Puedes ver el estado en tu panel de empleado</li>
                                    <li>El proceso de aprobación ha comenzado</li>
                                </ul>
                            </div>
                        </div>
                    `,
                    confirmButtonText: 'Ir al Panel',
                    allowOutsideClick: false,
                    timer: 5000,
                    timerProgressBar: true
                }).then((result) => {
                    if (data.redirect_url) {
                        window.location.href = data.redirect_url;
                    } else {
                        window.location.href = '/web';
                    }
                });
            } else {
                console.log('❌ ERROR: Solicitud fallida:', data);

                // Usar el nuevo sistema de manejo de errores
                showErrorModal(data, data.error);
                resetSubmitButton();
            }
        })
        .catch(function(error) {
            console.error('💥 ERROR:', error);

            let errorData;
            if (error.message.includes('JSON')) {
                errorData = {
                    error_code: 'COMMUNICATION_ERROR',
                    error: 'Hubo un problema procesando la respuesta del servidor.',
                    suggestion: 'Por favor intenta nuevamente. Si el problema persiste, contacta al administrador.'
                };
            } else {
                errorData = {
                    error_code: 'CONNECTION_ERROR',
                    error: 'No se pudo conectar con el servidor.',
                    suggestion: 'Verifica tu conexión a internet e intenta nuevamente.'
                };
            }

            showErrorModal(errorData, error.message);
            resetSubmitButton();
        });

        function resetSubmitButton() {
            console.log('🔄 Reseteando botón de envío');
            loadingSpinner.classList.add('hidden');
            submitText.innerHTML = '<i class="fas fa-paper-plane mr-2"></i>Enviar Solicitud';
            submitBtn.disabled = false;
        }
    });

    // Auto-update date_to when date_from changes
    document.getElementById('request_date_from').addEventListener('change', function() {
        console.log('📅 Cambio en fecha desde:', this.value);

        const activeCard = document.querySelector('.period-card.active');
        if (activeCard && ['morning', 'afternoon', 'custom_hours'].includes(activeCard.dataset.period)) {
            updateDateTo();
        }
    });

    // Smooth scrolling for better mobile experience
    const formElements = document.querySelectorAll('input, textarea, select');
    formElements.forEach(function(element) {
        element.addEventListener('focus', function() {
            const self = this;
            setTimeout(function() {
                self.scrollIntoView({
                    behavior: 'smooth',
                    block: 'center'
                });
            }, 300);
        });
    });

    // Add visual feedback for validation
    const requiredFields = ['holiday_status_id', 'request_date_from', 'private_name'];
    requiredFields.forEach(function(fieldId) {
        const field = document.getElementById(fieldId);
        if (field) {
            field.addEventListener('blur', function() {
                if (!this.value.trim()) {
                    this.classList.add('border-red-300', 'bg-red-50');
                    this.classList.remove('border-gray-200');
                } else {
                    this.classList.remove('border-red-300', 'bg-red-50');
                    this.classList.add('border-gray-200');
                }
            });

            field.addEventListener('input', function() {
                if (this.value.trim()) {
                    this.classList.remove('border-red-300', 'bg-red-50');
                    this.classList.add('border-green-300', 'bg-green-50');
                    const self = this;
                    setTimeout(function() {
                        self.classList.remove('border-green-300', 'bg-green-50');
                        self.classList.add('border-gray-200');
                    }, 2000);
                }
            });
        }
    });

    console.log('🚀 Sistema de permisos iniciado completamente');
});
//
